UPDATE TB_RESUME_POINT SET
    CUSTOMER_ID = #{customerId}, PRODUCT_TYPE = #{productType}, BIZ_CD = #{bizCd}, BIZ_NM = #{bizNm},
    PRODUCT_CD = #{productCd}, PRODUCT_NM = #{productNm}, PARTNER_CD = #{partnerCd}, STEP_NM = #{stepNm},
    STEP_NO = #{stepNo}, TOTAL_STEPS = #{totalSteps}, RESUME_URL = #{resumeUrl}, STATUS = #{status},
    STARTED_AT = #{startedAt}, LAST_ACTIVITY_AT = #{lastActivityAt}, EXPIRES_AT = #{expiresAt}
WHERE RESUME_ID = #{resumeId}
